<script>
 import {onMount} from 'svelte';import {assistantPresets} from '../assistant-presets';import {planningInstruction,defaultOutputFormat} from '../assistant-intent';import {Plus,X,ChevronUp,ChevronDown,Play,FolderOpen,ArrowUpRight,Check,RefreshCw,Square,Sparkles} from 'lucide-svelte';import {studio,current,scope,run,save,refresh,notify,jobs as reloadJobs,asset,clearDrafts,goSettings,importImages} from '../studio.svelte';import {api,clone,rgb,hex,stored,persist,bytes} from '../api';import {money} from '../cost';import ScopePicker from './ScopePicker.svelte';
 let instruction=$state(''),folder=$state(stored('assistant-output','')),recipe=$state(null),requestId=crypto.randomUUID(),submitted=$state(false),plan=$state({summary:'Local adjustments',steps:[],warnings:[],clarification:null,output:null}),sample=$state(null),split=$state(50),presetName=$state(''),presets=$state([]),op=$state('adjust'),configured=$state(false),usage=$state(null),localReport=$state(null);
 let plannedContext=$state('');
 const context=()=>JSON.stringify([studio.pid,scope(),instruction]);
 function usePreset(p){instruction=p.instruction;recipe=null;submitted=false;requestId=crypto.randomUUID();}
 const templates={adjust:{op:'adjust',exposure:0,contrast:1,saturation:1,temperature:0},rotate:{op:'rotate',degrees:90},flip:{op:'flip',axis:'horizontal'},crop:{op:'crop',x:0,y:0,width:1,height:1},resize:{op:'resize',width:1000,height:1000,fit:'pad',background:[255,255,255]},flatten:{op:'flatten',background:[255,255,255]},blur:{op:'blur',sigma:1},sharpen:{op:'sharpen',sigma:1,threshold:3},denoise:{op:'denoise',strength:3},auto_center:{op:'auto_center',padding:.08},deskew:{op:'deskew',max_degrees:10}};
 const labels={adjust:'Color',rotate:'Rotate',flip:'Flip',crop:'Crop',resize:'Resize / pad',flatten:'Fill transparency',blur:'Blur',sharpen:'Sharpen',denoise:'Denoise',auto_center:'Auto center',deskew:'Straighten',max_degrees:'Maximum degrees',maxBytes:'Maximum bytes'};
 $effect(()=>{if(studio.mode==='assistant')api('assistant_key_status').then(v=>configured=v).catch(()=>{});});
 onMount(()=>{api('assistant_presets').then(v=>presets=Object.entries(v).map(([name,plan])=>({name,plan}))).catch(e=>studio.error=e.message);api('assistant_key_status').then(v=>configured=v).catch(()=>{});reloadJobs().catch(()=>{});const timer=setInterval(()=>reloadJobs().catch(()=>{}),5000);return()=>clearInterval(timer);});
 $effect(()=>{JSON.stringify(plan);studio.pid;studio.aid;JSON.stringify(scope());sample=null;});
 async function choose(){const path=await api('pick_output');if(path){folder=path;persist('assistant-output',path);}return path;}
 async function prepare(){await run('Planning task',async()=>{recipe=null;const result=await api('hybrid_plan',{projectId:studio.pid,ids:[...scope()],instruction:planningInstruction(instruction)});result.recipe=defaultOutputFormat(instruction,result.recipe);recipe=result;plannedContext=context();if(result.recipe.clarification)studio.error=result.recipe.clarification;});}
 async function start(){if(!recipe||plannedContext!==context()||recipe.recipe.clarification)return;await run('Starting task',async()=>{if(!folder)await choose();if(!folder)return;await save(scope());await api('hybrid_start',{projectId:studio.pid,ids:[...scope()],instruction,recipe:clone(recipe.recipe),outputDir:folder,approved:true,clientRequestId:requestId});submitted=true;studio.processTab='jobs';await reloadJobs();notify('Background task started');});}
 async function parse(){await run('Planning local steps',async()=>{const r=await api('assistant_plan',{projectId:studio.pid,ids:[...scope()],instruction});plan=r.plan;usage=r;});}
 async function preview(){await run('Processing sample',async()=>{await save(scope());sample=await api('assistant_preview',{projectId:studio.pid,ids:[...scope()],plan:clone(plan)});});}
 async function apply(){await run('Applying local steps',async()=>{if(plan.output&&!folder)await choose();if(plan.output&&!folder)return;const sampleId=sample.sampleId;sample=null;localReport=await api('assistant_apply',{sampleId,outputDir:plan.output?folder:null});await refresh();clearDrafts(scope());if(asset())studio.draft=clone(asset().edit);notify('Local processing completed');});}
 function move(i,d){const j=i+d;if(j<0||j>=plan.steps.length)return;[plan.steps[i],plan.steps[j]]=[plan.steps[j],plan.steps[i]];}
</script>
<div class="workflow-panel assistant-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>Process</h1><span>{scope().length} {scope().length===1?'image':'images'}</span></div><div class="assistant-tabs segmented"><button class:active={studio.processTab==='auto'} onclick={()=>studio.processTab='auto'}>Assistant</button><button class:active={studio.processTab==='local'} onclick={()=>studio.processTab='local'}>Local steps</button><button class:active={studio.processTab==='jobs'} onclick={()=>studio.processTab='jobs'}>Tasks <span>{studio.jobs.length}</span></button></div>
{#if studio.processTab!=='jobs'}<ScopePicker/>{/if}
{#if !scope().length&&studio.processTab!=='jobs'}<div class="empty"><h2>Select images to process</h2><div class="button-row"><button class="primary" onclick={()=>importImages(false)}>Import images</button><button class="line-button" onclick={()=>{studio.mode='edit';studio.view='grid';}}>Open image grid</button></div></div>{:else if studio.processTab==='auto'}<div class="assistant-auto"><div class="assistant-images">{#each scope().slice(0,5) as id}<img src={studio.thumbs[id]} alt="Selected"/>{/each}</div><h2>What would you like to change?</h2><div class="assistant-presets" aria-label="Workflow presets">{#each assistantPresets as p}<button class:active={instruction===p.instruction} onclick={()=>usePreset(p)} disabled={submitted}><b>{p.name}</b><span>{p.detail}</span></button>{/each}</div><textarea aria-label="Processing instruction" bind:value={instruction} rows="5" placeholder="产品主图，800*800，100kb"></textarea><label>Output folder<div class="input-action"><input bind:value={folder} placeholder="Choose a folder" aria-label="Assistant output folder"/><button aria-label="Choose assistant output" onclick={()=>run('Choosing folder',choose)}><FolderOpen size={17}/></button></div></label><div class="assistant-start"><span class="hint">DeepSeek planning · Google Batch when needed</span><button class="primary" disabled={!configured||!instruction.trim()||!scope().length||!!studio.busy||submitted} onclick={prepare}><Sparkles size={15}/>{submitted?'Submitted':'Review plan'}</button></div>{#if !configured}<button class="text-button" onclick={()=>goSettings('assistant')}>Connect DeepSeek in Settings<ArrowUpRight size={13}/></button>{/if}{#if recipe&&plannedContext===context()}<div class="recipe-summary"><b>{recipe.recipe.summary}</b><span>{recipe.recipe.generation?'Google Batch + local processing':'Local processing'}</span><span>{recipe.recipe.output.width} × {recipe.recipe.output.height} · {recipe.recipe.output.format}</span><ol class="recipe-steps">{#each recipe.recipe.before as step}<li>{labels[step.op]||step.op}</li>{/each}{#if recipe.recipe.generation}<li>AI generation · {recipe.recipe.generation.resolution}<p>{recipe.recipe.generation.prompt}</p></li>{/if}{#each recipe.recipe.after as step}<li>{labels[step.op]||step.op}</li>{/each}<li>Export {recipe.recipe.output.format.toUpperCase()} · {recipe.recipe.output.maxBytes?`≤ ${Math.round(recipe.recipe.output.maxBytes/1000)} KB`:'No size limit'}</li></ol>{#if !recipe.recipe.clarification}<button class="primary" disabled={submitted||!!studio.busy} onclick={start}>{recipe.recipe.generation?'Approve AI & start':'Start processing'}</button>{/if}{#each recipe.recipe.warnings||[] as warning}<p>{warning}</p>{/each}</div>{/if}{#if submitted}<button class="line-button" onclick={()=>{submitted=false;requestId=crypto.randomUUID();instruction='';recipe=null;}}>New task</button>{/if}</div>
{:else if studio.processTab==='local'}<div class="local-layout"><div class="local-plan"><div class="instruction-row"><textarea aria-label="Local instruction" bind:value={instruction} placeholder="Describe local edits, or add steps below." rows="2"></textarea><button class="line-button" disabled={!configured||!instruction.trim()||!!studio.busy} onclick={parse}>Plan</button></div>{#if usage}<span class="hint">{usage.usage?.total_tokens||0} tokens{usage.cost?` · $${usage.cost.minimumUsd.toFixed(6)}–$${usage.cost.maximumUsd.toFixed(6)}`:''}</span>{/if}<div class="step-add"><select bind:value={op} aria-label="Add operation">{#each Object.keys(templates) as key}<option value={key}>{labels[key]}</option>{/each}</select><button class="line-button" onclick={()=>plan.steps.push(clone(templates[op]))} disabled={plan.steps.length>=20}><Plus size={14}/>Add step</button></div><div class="steps">{#each plan.steps as step,i}<div class="step"><div class="step-heading"><b>{i+1}. {labels[step.op]||step.op}</b><div><button aria-label={`Move step ${i+1} up`} disabled={i===0} onclick={()=>move(i,-1)}><ChevronUp size={14}/></button><button aria-label={`Move step ${i+1} down`} disabled={i===plan.steps.length-1} onclick={()=>move(i,1)}><ChevronDown size={14}/></button><button aria-label={`Remove step ${i+1}`} onclick={()=>plan.steps.splice(i,1)}><X size={14}/></button></div></div><div class="field-grid">{#each Object.entries(step).filter(([k])=>k!=='op') as [key,value]}<label>{labels[key]||key.replaceAll('_',' ')}{#if Array.isArray(value)}<input aria-label={`${step.op} ${key}`} type="color" value={hex(value)} onchange={e=>step[key]=rgb(e.target.value)}/>{:else if typeof value==='number'}<input aria-label={`${step.op} ${key}`} type="number" step={['width','height','threshold','degrees'].includes(key)?1:.05} value={value} onchange={e=>step[key]=Number(e.target.value)}/>{:else}<select aria-label={`${step.op} ${key}`} value={value} onchange={e=>step[key]=e.target.value}>{#each key==='axis'?['horizontal','vertical']:['pad','crop'] as option}<option>{option}</option>{/each}</select>{/if}</label>{/each}</div></div>{/each}</div><label class="checkbox-label"><input type="checkbox" checked={!!plan.output} onchange={e=>plan.output=e.target.checked?{format:'webp',width:1000,height:1000,fit:'pad',maxBytes:500000,background:[255,255,255]}:null}/>Export after processing</label>{#if plan.output}<div class="field-grid"><label>Format<select bind:value={plan.output.format}><option>webp</option><option>png</option><option>jpeg</option></select></label><label>Fit<select bind:value={plan.output.fit}><option>pad</option><option>crop</option></select></label>{#each ['width','height','maxBytes'] as key}<label>{labels[key]||key}<input type="number" min="1" bind:value={plan.output[key]}/></label>{/each}<label>Background<input type="color" value={hex(plan.output.background)} onchange={e=>plan.output.background=rgb(e.target.value)}/></label></div>{/if}{#if plan.clarification}<p class="inline-error">{plan.clarification}</p>{/if}{#each plan.warnings||[] as warning}<p class="hint">{warning}</p>{/each}<div class="preset-save"><input aria-label="Preset name" placeholder="Preset name" bind:value={presetName}/><button class="line-button" disabled={!presetName.trim()||!!studio.busy} onclick={()=>run('Saving preset',async()=>{await api('assistant_save_preset',{name:presetName,plan:clone(plan)});presets=Object.entries(await api('assistant_presets')).map(([name,plan])=>({name,plan}));notify('Preset saved');})}>Save</button></div>{#if presets.length}<select aria-label="Load local preset" onchange={e=>{if(e.target.value==='')return;const p=presets[Number(e.target.value)];if(p)plan=clone(p.plan);}}><option value="">Load preset</option>{#each presets as p,i}<option value={i}>{p.name}</option>{/each}</select>{/if}</div><div class="sample-panel"><h3>Sample</h3><p class="sample-name">{current()?.assets.find(a=>a.id===scope()[0])?.name}</p>{#if sample}<div class="sample-comparison"><img src={`data:image/png;base64,${sample.after}`} alt="Processed sample"/><div class="compare-before" style:clip-path={`inset(0 ${100-split}% 0 0)`}><img src={`data:image/png;base64,${sample.before}`} alt="Original sample"/></div><div class="compare-line" style:left={`${split}%`}></div><input class="compare-slider" type="range" min="0" max="100" bind:value={split} aria-label="Sample comparison"/></div>{:else}<img class="sample-original" src={studio.thumbs[scope()[0]]} alt="Selected sample"/>{/if}<div class="button-row"><button class="line-button" disabled={!!studio.busy||!scope().length||!plan.steps.length||!!plan.clarification} onclick={preview}>Try one image</button><button class="primary" disabled={!sample||!!studio.busy} onclick={apply}><Check size={14}/>Apply to {scope().length}</button></div>{#if localReport}<div class="local-report"><h3>Results</h3>{#each localReport.items||localReport.results||[] as item}<p>{item.name||current()?.assets.find(a=>a.id===item.assetId)?.name||'Image'} · {item.status||item.error||'Saved'}</p>{/each}<button class="text-button" onclick={()=>studio.mode='edit'}>Return to editor<ArrowUpRight size={14}/></button></div>{/if}</div></div>
{:else}<div class="task-list"><div class="section-row"><h3>Background tasks</h3><button aria-label="Refresh tasks" onclick={()=>run('Refreshing tasks',reloadJobs)}><RefreshCw size={15}/></button></div>{#each studio.jobs as job}<article class="task"><div class="task-heading"><b>{job.recipe.summary}</b><span class={`job-state ${job.state}`}>{job.state}</span></div><p>{job.instruction}</p><div class="task-details"><span>{job.items.filter(i=>i.stage==='done').length} / {job.items.length} images</span><span>{job.estimatedUsd!=null?money(job.estimatedUsd,studio.currency,studio.exchangeRate):''}</span></div>{#if job.error}<p class="inline-error">{job.error}</p>{/if}<details><summary>Image results</summary>{#each job.items as item}<div class="task-item"><span>{item.name}</span><b>{item.stage}</b>{#if item.error}<small>{item.error}</small>{/if}{#each item.warnings||[] as w}<small>{w}</small>{/each}</div>{/each}</details><div class="button-row"><button class="line-button" disabled={!job.items.some(i=>i.exported)} onclick={()=>run('Opening output',()=>api('hybrid_open_output',{jobId:job.id}))}><FolderOpen size={14}/>Open output</button>{#if !['completed','partial','failed','cancelled'].includes(job.state)}<button class="text-button" onclick={()=>run('Cancelling',async()=>{await api('hybrid_cancel',{jobId:job.id});await reloadJobs();})}><Square size={12}/>Cancel</button>{/if}<button class="text-button" onclick={()=>run('Acknowledging',async()=>{await api('hybrid_ack',{jobId:job.id});await reloadJobs();})}>Mark read</button></div></article>{/each}{#if !studio.jobs.length}<div class="empty small"><h2>No background tasks</h2></div>{/if}</div>{/if}</div>

